using System.Text;

namespace Atthree.ProjectSetup
{
    /// <summary>The contents of .gitignore and .gitattributes for a Unity project.</summary>
    public static class GitFiles
    {
        const string IgnoreBase =
@"# ---- Unity: generated folders (Unity rebuilds them) ----
/[Ll]ibrary/
/[Tt]emp/
/[Oo]bj/
/[Bb]uild/
/[Bb]uilds/
/[Ll]ogs/
/[Uu]ser[Ss]ettings/
/[Mm]emoryCaptures/
/[Rr]ecordings/

# Meta files are only ignored together with their asset
!/[Aa]ssets/**/*.meta

# Generated by packages
/[Aa]ssets/[Pp]lugins/[Ee]ditor/[Jj]et[Bb]rains*
/[Aa]ssets/AddressableAssetsData/*/*.bin*
/[Aa]ssets/StreamingAssets/aa.meta
/[Aa]ssets/StreamingAssets/aa/*

# ---- IDEs ----
.vs/
.vscode/
.idea/
.consulo/
*.csproj
*.unityproj
*.sln
*.slnx
*.suo
*.tmp
*.user
*.userprefs
*.pidb
*.booproj
*.svd
*.pdb
*.mdb
*.opendb
*.VC.db
*.pidb.meta
*.pdb.meta
*.mdb.meta

# ---- Builds and crash files ----
*.apk
*.aab
*.unitypackage
*.app
crashlytics-build.properties
sysinfo.txt
mono_crash.*
.gradle/
ExportedObj/

# ---- OS ----
.DS_Store
Thumbs.db
desktop.ini
";

        public static string Gitignore(string extraLines)
        {
            var sb = new StringBuilder(IgnoreBase.Replace("\r\n", "\n"));
            var extra = (extraLines ?? "").Replace("\r\n", "\n").Trim();
            if (extra.Length > 0)
            {
                sb.Append("\n# ---- This project ----\n");
                sb.Append(extra).Append('\n');
            }
            return sb.ToString();
        }

        /// <summary>Unity's text assets (YAML)</summary>
        static readonly string[] TextAssets =
        {
            "unity", "prefab", "asset", "mat", "anim", "controller", "overrideController", "mask", "meta",
            "physicMaterial", "physicsMaterial2D", "playable", "signal", "lighting", "preset", "mixer",
            "spriteatlas", "spriteatlasv2", "terrainlayer", "shadervariants", "renderTexture", "cubemap",
            "flare", "guiskin", "fontsettings", "brush", "giparams", "inputactions", "uxml", "uss",
        };

        static readonly string[] BinaryAssets =
        {
            // images
            "png", "jpg", "jpeg", "gif", "psd", "tga", "tif", "tiff", "exr", "hdr", "bmp", "iff", "pict",
            // models
            "fbx", "obj", "blend", "dae", "3ds", "max", "ma", "mb",
            // audio
            "wav", "mp3", "ogg", "aif", "aiff", "flac",
            // video
            "mp4", "mov", "webm", "avi",
            // fonts
            "ttf", "otf",
            // other
            "dll", "so", "a", "dylib", "zip", "7z", "rar", "unitypackage", "pdf", "bytes", "bank",
        };

        public static string Gitattributes(bool useLfs)
        {
            var sb = new StringBuilder();
            sb.Append("# Line endings are decided by git, not by each computer\n");
            sb.Append("* text=auto\n\n");
            sb.Append("*.cs text diff=csharp\n");
            sb.Append("*.shader text\n*.hlsl text\n*.cginc text\n*.compute text\n*.json text\n*.md text\n\n");

            sb.Append("# Unity YAML assets: text with LF endings, like Unity writes them\n");
            foreach (var ext in TextAssets) sb.Append($"*.{ext} text eol=lf\n");

            sb.Append(useLfs
                ? "\n# Large files are stored with Git LFS (run 'git lfs install' once on each computer)\n"
                : "\n# Binary files: never changed, diffed or merged as text\n");
            var rule = useLfs ? "filter=lfs diff=lfs merge=lfs -text" : "binary";
            foreach (var ext in BinaryAssets) sb.Append($"*.{ext} {rule}\n");
            return sb.ToString();
        }
    }
}
